<script setup lang="ts">import { watch, onBeforeUnmount } from 'vue';import { X } from 'lucide-vue-next';import FiltroEquivalenciasList from './FiltroEquivalenciasList.vue';import type { EquipoEngraseListItem, EquipoFiltroDetalle, FiltroEquivalenciaRow } from '@/stores/dbequipos/engrase/filtrosEngrase.types';const props=defineProps<{open:boolean;equipo:EquipoEngraseListItem|null;filtro:EquipoFiltroDetalle|null;equivalencias:FiltroEquivalenciaRow[];loadingEquivalencias:boolean;errorEquivalencias:string|null}>();const emit=defineEmits<{close:[];retryEquivalencias:[]}>();const closeOnEscape=(event:KeyboardEvent)=>{if(event.key==='Escape'&&props.open)emit('close')};watch(()=>props.open,open=>open?window.addEventListener('keydown',closeOnEscape):window.removeEventListener('keydown',closeOnEscape));onBeforeUnmount(()=>window.removeEventListener('keydown',closeOnEscape));</script><template><aside class="detail" :class="{open}" :aria-hidden="!open"><template v-if="filtro"><header><h2>Detalle del filtro</h2><button type="button" aria-label="Cerrar detalle" @click="$emit('close')"><X class="w-5 h-5"/></button></header><section><h3>{{filtro.tipoFiltro.nombre}}</h3><dl><dt>Código original</dt><dd>{{filtro.filtro.codigo}}</dd><dt>Cantidad</dt><dd>x{{filtro.cantidad}}</dd><dt>Etapas</dt><dd>{{equipo?.etapas.map(x=>x.nombre).join(', ')||'Sin etapa'}}</dd><dt>En lista de compras</dt><dd>{{filtro.filtro.esta_en_lista_compras?'Sí':'No'}}</dd></dl></section><section><h3>Equivalencias</h3><p v-if="loadingEquivalencias">Cargando…</p><p v-else-if="errorEquivalencias">{{errorEquivalencias}} <button @click="$emit('retryEquivalencias')">Reintentar</button></p><FiltroEquivalenciasList v-else :equivalencias="equivalencias"/></section></template><p v-else class="hint">Seleccione un filtro para revisar su detalle.</p></aside></template><style scoped>.detail{min-height:0;padding:1rem;border:1px solid #e6edf7;border-radius:1rem;background:#fff;overflow:auto}.detail header{display:flex;justify-content:space-between;align-items:center}.detail h2{font-size:1rem;color:#14265a}.detail section{margin-top:1rem;padding-top:1rem;border-top:1px solid #eef2f7}.detail h3{margin:0 0 .8rem;color:#172554;font-size:.85rem}.detail dl{display:grid;grid-template-columns:1fr auto;gap:.7rem;font-size:.78rem}.detail dt{color:#64748b}.detail dd{margin:0;color:#172554;font-weight:700}.hint{color:#64748b;font-size:.8rem;text-align:center;padding:2rem 0}@media(max-width:900px){.detail{position:fixed;z-index:40;inset:auto 0 0 0;max-height:76vh;border-radius:1rem 1rem 0 0;transform:translateY(105%);transition:transform .2s ease;box-shadow:0 -8px 30px #17255433}.detail.open{transform:translateY(0)}}</style>
